mapper.select:
select DOMAIN_ID ,DOMAIN_NM ,DOMAIN_GRP_NM ,DOMAIN_CLSF_NM ,DOMAIN_DESC ,DATA_TYPE ,DATA_LEN ,DATA_DECIMAL_LEN ,DATA_UNIT ,STOR_FMT ,EXPR_FMT_LST ,ALLOW_VAL_LST ,COMM_STND_YN ,PRIV_YN ,ENCR_YN ,MAGNTD_ORD ,APRV_YN ,APRV_USER_ID ,to_char(to_timestamp(CRET_DT,'YYYYMMDDHH24MISS'),'YYYY-MM-DD HH24:MI:SS') as CRET_DT ,CRET_USER_ID ,to_char(to_timestamp(UPDT_DT,'YYYYMMDDHH24MISS'),'YYYY-MM-DD HH24:MI:SS') as UPDT_DT ,UPDT_USER_ID ,to_char(to_timestamp(APRV_STAT_UPDT_DT,'YYYYMMDDHH24MISS'),'YYYY-MM-DD HH24:MI:SS') as APRV_STAT_UPDT_DT ,REQ_SYS_CD ,(select SYS_NM from TB_SYS_INFO where sys_cd = REQ_SYS_CD) as REQ_SYS_NM from TB_DOMAIN where 1=1 AND DICT_ID = #{dictId}
AND DOMAIN_NM ILIKE '%' || #{schNm} || '%'
AND APRV_YN = #{schAprvYn}
AND COMM_STND_YN = #{schCommStndYn}
AND COALESCE(PRIV_YN, 'N') = #{schPrivYn}
AND COALESCE(ENCR_YN, 'N') = #{schEncrYn}
AND DOMAIN_GRP_NM ILIKE '%' || #{schDomainGrpNm} || '%'
AND DATA_TYPE ILIKE '%' || #{schDataType} || '%'
AND CAST(DATA_LEN AS TEXT) = #{schDataLen}
order by DOMAIN_NM

mapper.insert:
INSERT INTO TB_DOMAIN
(
 DOMAIN_ID
 ,DOMAIN_NM			
 ,DOMAIN_GRP_NM
 ,DOMAIN_CLSF_NM		
 ,DOMAIN_DESC		
 ,DATA_TYPE	
 ,DATA_LEN
 ,DATA_DECIMAL_LEN	
 ,DATA_UNIT
 ,STOR_FMT 		
 ,EXPR_FMT_LST			
 ,ALLOW_VAL_LST	
 ,COMM_STND_YN
 ,PRIV_YN
 ,ENCR_YN
 ,MAGNTD_ORD
 ,APRV_YN
 ,APRV_USER_ID
 ,CRET_DT
 ,CRET_USER_ID
 ,APRV_STAT_UPDT_DT
 ,REQ_SYS_CD
 ,DICT_ID
)
VALUES
(
  #{id}
 ,#{domainNm}
 ,#{domainGrpNm}
 ,#{domainClsfNm}
 ,#{domainDesc}
 ,#{dataType}
 ,#{dataLen, jdbcType=SMALLINT}
 ,#{dataDecimalLen, jdbcType=SMALLINT}
 ,#{dataUnit, jdbcType=VARCHAR}
 ,#{storFmt, jdbcType=VARCHAR}
 ,#{exprFmtLst, typeHandler=com.ndata.common.handler.ArrayTypeHandler}
 ,#{allowValLst, typeHandler=com.ndata.common.handler.ArrayTypeHandler}
 ,#{commStndYn, jdbcType=VARCHAR}
 ,COALESCE(#{privYn, jdbcType=VARCHAR}, 'N')
 ,COALESCE(#{encrYn, jdbcType=VARCHAR}, 'N')
 ,#{magntdOrd, jdbcType=VARCHAR}
 ,#{aprvYn, jdbcType=VARCHAR}
 ,#{aprvUserId, jdbcType=VARCHAR}
 ,to_char(now(), 'YYYYMMDDHH24MISS')
 ,#{cretUserId, jdbcType=VARCHAR}
 ,to_char(now(), 'YYYYMMDDHH24MISS')
 ,#{reqSysCd, jdbcType=VARCHAR}
 ,COALESCE(#{dictId, jdbcType=VARCHAR}, 'DEFAULT')
)

mapper.update:
UPDATE TB_DOMAIN
DOMAIN_NM = #{domainNm}, DOMAIN_GRP_NM = #{domainGrpNm}, DOMAIN_CLSF_NM = #{domainClsfNm}, DOMAIN_DESC = #{domainDesc}, DATA_TYPE = #{dataType}, DATA_LEN = #{dataLen}, DATA_DECIMAL_LEN = #{dataDecimalLen}, DATA_UNIT = #{dataUnit, jdbcType=VARCHAR}, STOR_FMT = #{storFmt, jdbcType=VARCHAR}, EXPR_FMT_LST = #{exprFmtLst, typeHandler=com.ndata.common.handler.ArrayTypeHandler}, ALLOW_VAL_LST = #{allowValLst, typeHandler=com.ndata.common.handler.ArrayTypeHandler}, COMM_STND_YN = #{commStndYn, jdbcType=VARCHAR}, PRIV_YN = #{privYn}, ENCR_YN = #{encrYn}, MAGNTD_ORD = #{magntdOrd, jdbcType=VARCHAR}, UPDT_DT = to_char(now(), 'YYYYMMDDHH24MISS'), UPDT_USER_ID = #{updtUserId}, REQ_SYS_CD = #{reqSysCd, jdbcType=VARCHAR}
WHERE DOMAIN_ID = #{id}

UPDATE TB_DOMAIN_GRP
DOMAIN_GRP_NM = #{domainGrpNm}, COMM_STND_YN = #{commStndYn}, PARENT_GRP_ID = NULLIF(#{parentGrpId}, ''), DFLT_DATA_TYPE = NULLIF(#{dfltDataType}, ''), CLSF_WORD_NM = NULLIF(#{clsfWordNm}, ''), SORT_ORDER = #{sortOrder}, UPDT_DT = to_char(now(), 'YYYYMMDDHH24MISS'), UPDT_USER_ID = #{updtUserId}
WHERE DOMAIN_GRP_ID = #{id}

mapper.insert:
           INSERT INTO TB_DOMAIN_CLSF
           (
				 DOMAIN_CLSF_ID
				,DOMAIN_CLSF_NM	
				,DOMAIN_GRP_NM		
				,COMM_STND_YN	
				,CRET_DT			
				,CRET_USER_ID
            ,DICT_ID
           )
           VALUES
           (
             #{id}
            ,#{domainClsfNm}
            ,#{domainGrpNm}
            ,#{commStndYn, jdbcType=VARCHAR}
            ,to_char(now(), 'YYYYMMDDHH24MISS')
            ,#{cretUserId, jdbcType=VARCHAR}
            ,COALESCE(#{dictId, jdbcType=VARCHAR}, 'DEFAULT')
           )

mapper.update:
UPDATE TB_DOMAIN_CLSF
DOMAIN_CLSF_NM = #{domainClsfNm}, DOMAIN_GRP_NM = #{domainGrpNm}, COMM_STND_YN = #{commStndYn}, UPDT_DT = to_char(now(), 'YYYYMMDDHH24MISS'), UPDT_USER_ID = #{updtUserId}
WHERE DOMAIN_CLSF_ID = #{id}
